 const controls=new OrbitControls(camera,renderer.domElement);controls.target.set(0,0,0);controls.enableDamping=true;controls.maxPolarAngle=Math.PI*.46;controls.minDistance=14;controls.maxDistance=65;controls.enablePan=false;
 scene.add(new T.HemisphereLight(0xeaf7ff,0x4c5b68,2.3));const sun=new T.DirectionalLight(0xfff2df,3);sun.position.set(-12,25,15);sun.castShadow=true;sun.shadow.mapSize.set(1024,1024);sun.shadow.camera.left=-24;sun.shadow.camera.right=24;sun.shadow.camera.top=24;sun.shadow.camera.bottom=-24;sun.shadow.bias=-.001;scene.add(sun);scene.add(new T.AmbientLight(0x85c8f5,.55));
 const office=new T.Group(),galaxy=new T.Group();scene.add(office,galaxy);galaxy.visible=false;
 const mats={floor:new T.MeshStandardMaterial({color:0xd6e0e6,roughness:.55,metalness:.1}),white:new T.MeshStandardMaterial({color:0xf4f4ed,roughness:.55}),wood:new T.MeshStandardMaterial({color:0xb99b76,roughness:.8}),dark:new T.MeshStandardMaterial({color:0x17374a,roughness:.45,metalness:.3}),glass:new T.MeshPhysicalMaterial({color:0x9acada,transparent:true,opacity:.2,roughness:.12,metalness:.1,depthWrite:false}),green:new T.MeshStandardMaterial({color:0x417e65,roughness:1}),gold:new T.MeshStandardMaterial({color:0xc8a96d,metalness:.7,roughness:.3})};
 function box(g,x,y,z,w,h,d,mat){const m=new T.Mesh(new T.BoxGeometry(w,h,d),mat);m.position.set(x,y,z);m.castShadow=true;m.receiveShadow=true;g.add(m);return m;}
